"use strict";document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll('form[role="search"]').forEach(e=>{const t=e.querySelector('input[type="search"]');if(!t)return;const r=()=>{const e=t.value.trim().length;t.setCustomValidity(e<2?"Saisissez au moins deux caractères.":e>120?"Limitez votre recherche à 120 caractères.":"")};t.addEventListener("input",r),e.addEventListener("submit",t=>{r(),e.reportValidity()||(t.preventDefault(),t.stopImmediatePropagation())},!0)})});
